ved_by","type":"text","default":null,"not_null":true},{"name":"approved_at","type":"timestamp with time zone","default":"clock_timestamp()","not_null":true}],"constraints":[{"name":"metric_snapshots_mapping_id_fkey","definition":"FOREIGN KEY (mapping_id) REFERENCES finance_apm_private.metric_mappings(id)"},{"name":"metric_snapshots_mapping_id_year_quarter_key","definition":"UNIQUE (mapping_id, year, quarter)"},{"name":"metric_snapshots_pkey","definition":"PRIMARY KEY (id)"}],"indexes":["CREATE INDEX metric_snapshots_mapping ON finance_apm_private.metric_snapshots USING btree (mapping_id)","CREATE UNIQUE INDEX metric_snapshots_mapping_id_year_quarter_key ON finance_apm_private.metric_snapshots USING btree (mapping_id, year, quarter)","CREATE UNIQUE INDEX metric_snapshots_pkey ON finance_apm_private.metric_snapshots USING btree (id)"]}]}$apm_catalog$::jsonb;
  item jsonb;
  p pg_catalog.pg_proc%rowtype;
  n pg_catalog.pg_namespace%rowtype;
  c pg_catalog.pg_class%rowtype;
  t pg_catalog.pg_trigger%rowtype;
  signature text;
  migration record;
  row_count integer;
begin
  if pg_catalog.to_regclass('supabase_migrations.schema_migrations') is null then
    raise exception using errcode='55000',message='APM adoption ledger is missing';
  end if;
  -- Name and exact single-statement bytes are part of the reviewed provenance.
  for item in select value from pg_catalog.jsonb_array_elements(expected->'ledger') loop
    select version,name,statements into migration
      from supabase_migrations.schema_migrations where version=item->>'version';
    if not found or migration.name is distinct from item->>'name'
       or pg_catalog.cardinality(migration.statements) is distinct from 1
       or pg_catalog.md5(migration.statements[1]) is distinct from item->>'statement_md5'
       or pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(migration.statements[1],'UTF8')),'hex')
          is distinct from item->>'statement_sha256' then
      raise exception using errcode='55000',message='APM adoption ledger drifted: '||(item->>'version');
    end if;
  end loop;
  select count(*) into row_count from supabase_migrations.schema_migrations
    where name ~ '^apm_';
  if row_count <> pg_catalog.jsonb_array_length(expected->'ledger') then
    raise exception using errcode='55000',message='APM adoption ledger contains an unreviewed migration';
  end if;

  select * into n from pg_catalog.pg_namespace where nspname='finance_apm_private';
  if n.oid is null or pg_catalog.pg_get_userbyid(n.nspowner) is distinct from expected#>>'{schema,owner}'
     or n.nspacl::text is distinct from expected#>>'{schema,acl}'
     or pg_catalog.has_schema_privilege('anon',n.oid,'USAGE')
     or not pg_catalog.has_schema_privilege('authenticated',n.oid,'USAGE')
     or not pg_catalog.has_schema_privilege('service_role',n.oid,'USAGE') then
    raise exception using errcode='55000',message='APM adoption schema authority drifted';
  end if;
  select count(*) into row_count from pg_catalog.pg_proc fn
    join pg_catalog.pg_namespace ns on ns.oid=fn.pronamespace
    where ns.nspname='finance_apm_private' or (ns.nspname='public' and fn.proname ~ '^finance_apm_');
  if row_count <> pg_catalog.jsonb_array_length(expected->'functions') then
    raise exception using errcode='55000',message='APM adoption function set drifted';
  end if;
  -- These are final definitions after both wrapper renames, not the initial
  -- CREATE statements of an earlier migration.
  for item in select value from pg_catalog.jsonb_array_elements(expected->'functions') loop
    signature=pg_catalog.format('%I.%I(%s)',item->>'schema',item->>'name',item->>'argument_types');
    select * into p from pg_catalog.pg_proc where oid=pg_catalog.to_regprocedure(signature);
    if p.oid is null or pg_catalog.md5(p.prosrc) is distinct from item->>'source_md5'
       or pg_catalog.md5(pg_catalog.pg_get_functiondef(p.oid)) is distinct from item->>'definition_md5'
       or pg_catalog.pg_get_userbyid(p.proowner) is distinct from item->>'owner'
       or p.prosecdef is distinct from (item->>'security_definer')::boolean
       or p.provolatile::text is distinct from item->>'volatility'
       or pg_catalog.to_jsonb(p.proconfig) is distinct from item->'settings'
       or p.proacl::text is distinct from item->>'acl'
       or pg_catalog.pg_get_function_identity_arguments(p.oid) is distinct from item->>'identity_arguments'
       or pg_catalog.pg_get_function_result(p.oid) is distinct from item->>'return_type'
       or pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE')
       or pg_catalog.has_function_privilege('authenticated',p.oid,'EXECUTE') is distinct from (item->>'authenticated_execute')::boolean
       or pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE') is distinct from (item->>'service_role_execute')::boolean
       or exists(select 1 from pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a
         where a.grantee=0 and a.privilege_type='EXECUTE') then
      raise exception using errcode='55000',message='APM adoption function body or authority drifted: '||signature;
    end if;
  end loop;
  select count(*) into row_count from pg_catalog.pg_class cl
    join pg_catalog.pg_namespace ns on ns.oid=cl.relnamespace
    where ns.nspname='finance_apm_private' and cl.relkind in ('r','p','v','m','f');
  if row_count <> pg_catalog.jsonb_array_length(expected->'tables') then
    raise exception using errcode='55000',message='APM adoption table set drifted';
  end if;
  for item in select value from pg_catalog.jsonb_array_elements(expected->'tables') loop
    select * into c from pg_catalog.pg_class
      where oid=pg_catalog.to_regclass(pg_catalog.format('finance_apm_private.%I',item->>'name'));
    if c.oid is null or c.relkind<>'r'
       or pg_catalog.pg_get_userbyid(c.relowner) is distinct from item->>'owner'
       or c.relrowsecurity is distinct from (item->>'rls')::boolean
       or c.relforcerowsecurity is distinct from (item->>'force_rls')::boolean
       or c.relacl::text is distinct from item->>'acl'
       or exists(select 1 from pg_catalog.pg_policy where polrelid=c.oid)
       or exists(select 1 from pg_catalog.pg_attribute where attrelid=c.oid and attacl is not null) then
      raise exception using errcode='55000',message='APM adoption table authority drifted: '||(item->>'name');
    end if;
    -- The reviewed unique indexes and foreign keys are business safeguards:
    -- RLS alone does not prevent duplicate reversals or orphaned receipts.
    if (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'name',a.attname,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),
          'not_null',a.attnotnull,'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid)) order by a.attnum)
        from pg_catalog.pg_attribute a left join pg_catalog.pg_attrdef d
          on d.adrelid=a.attrelid and d.adnum=a.attnum
        where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped) is distinct from item->'columns'
       or (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'name',co.conname,'definition',pg_catalog.pg_get_constraintdef(co.oid)) order by co.conname)
        -- PostgreSQL 18 additionally catalogs NOT NULL constraints; their
        -- semantics are pinned for every column by attnotnull above.
        from pg_catalog.pg_constraint co where co.conrelid=c.oid and co.contype<>'n') is distinct from item->'constraints'
       or exists(select 1 from pg_catalog.pg_constraint co where co.conrelid=c.oid and not co.convalidated)
       or (select pg_catalog.jsonb_agg(pg_catalog.pg_get_indexdef(i.indexrelid) order by i.indexrelid::regclass::text)
        from pg_catalog.pg_index i where i.indrelid=c.oid) is distinct from item->'indexes'
       or exists(select 1 from pg_catalog.pg_index i where i.indrelid=c.oid
          and (not i.indisvalid or not i.indisready or not i.indislive)) then
      raise exception using errcode='55000',message='APM adoption table structure drifted: '||(item->>'name');
    end if;
  end loop;
  select count(*) into row_count from pg_catalog.pg_trigger tr
    join pg_catalog.pg_class cl on cl.oid=tr.tgrelid
    join pg_catalog.pg_namespace ns on ns.oid=cl.relnamespace
    join pg_catalog.pg_proc fn on fn.oid=tr.tgfoid
    join pg_catalog.pg_namespace fns on fns.oid=fn.pronamespace
    where not tr.tgisinternal and (ns.nspname='finance_apm_private' or fns.nspname='finance_apm_private'
      or tr.tgname in ('apm_receipt_voucher_guard','apm_receipt_ledger_guard'));
  if row_count <> pg_catalog.jsonb_array_length(expected->'triggers') then
    raise exception using errcode='55000',message='APM adoption trigger set drifted';
  end if;
  for item in select value from pg_catalog.jsonb_array_elements(expected->'triggers') loop
    select * into t from pg_catalog.pg_trigger
      where tgrelid=pg_catalog.to_regclass(pg_catalog.format('%I.%I',item->>'schema',item->>'table'))
        and tgname=item->>'name' and not tgisinternal;
    if t.oid is null or t.tgenabled::text is distinct from item->>'enabled'
       or t.tgtype is distinct from (item->>'type')::smallint
       or t.tgfoid is distinct from pg_catalog.to_regprocedure(item->>'function')
       or pg_catalog.pg_get_triggerdef(t.oid) is distinct from item->>'definition' then
      raise exception using errcode='55000',message='APM adoption trigger drifted: '||(item->>'table')||'.'||(item->>'name');
    end if;
  end loop;
end
$apm_adoption_guard$;
select 'FINANCE_APM_ADOPTION_POSTFLIGHT_OK'::text as result;
